INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(30611, 'Revelation 20:13', 'Revelation', 20, 13, 'بحر چې کوم مړي ساتلي وو، هغه یې بېرته ورکړل او مرګ او قبر هم هغه بېرته ورکړل او د هرچا قضاوت د هغه د عمل له مخې وشو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_13.mp3', '', 1761754199, 1761754199),
(30612, 'Revelation 20:14', 'Revelation', 20, 14, 'بیا مرګ او قبر د اور بحیرې ته وغورځول شول. د بحر دا اور دوهم مرګ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_14.mp3', '', 1761754199, 1761754199),
(30613, 'Revelation 20:15', 'Revelation', 20, 15, 'د چا نوم چې د ژوندون په کتاب کې نه ؤ لیکل شوی، هغه د اور بحیرې ته وغورځول شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_15.mp3', '', 1761754199, 1761754199),
(30614, 'Mark 2:1', 'Mark', 2, 1, 'څو ورځې وروسته کله چې عیسی بېرته کپرناحوم ته لاړ، نو خلک خبر شول چې هغه په کور کې دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_1.mp3', '', 1761754199, 1761754199),
(30615, 'Mark 2:2', 'Mark', 2, 2, 'هلته دومره زیات خلک راټول شول چې نور ځای نه ؤ، تر دې چې د کور د دروازې مخې ته هم ځای پاتې نه شو او عیسی هغوی ته د خدای د کلام وعظ کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_2.mp3', '', 1761754199, 1761754199),
(30616, 'Mark 2:3', 'Mark', 2, 3, 'په دې وخت کې څلورو کسانو یو شل سړی نیولی ؤ او عیسی ته یې راوست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_3.mp3', '', 1761754199, 1761754199),
(30617, 'Mark 2:4', 'Mark', 2, 4, 'خو د ګڼې‌ګوڼې له امله یې ونه شو کولای چې عیسی ته ورنژدې شي، نو هغوی د هغې کوټې چت چې عیسی په کې ؤ، سوری کړ او د هغه سوري له لارې یې هغه شل سړی په بستره کې ورښکته کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_4.mp3', '', 1761754199, 1761754199),
(30618, 'Mark 2:5', 'Mark', 2, 5, 'کله چې عیسی د هغوی ایمان ولیده، نو هغه شل سړي ته یې وویل: «زویه، ستا ګناهونه وبخښل شول.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_5.mp3', '', 1761754199, 1761754199),
(30619, 'Mark 2:6', 'Mark', 2, 6, 'په هغه ځای کې د شریعت یو څو عالمان ناست وو، هغوی د خپل ځان سره وویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_6.mp3', '', 1761754199, 1761754199),
(30620, 'Mark 2:7', 'Mark', 2, 7, '«دا سړی ولې داسې خبرې کوي؟ هغه کفر وایي. ایا بې له خدایه څوک کولای شي چې ګناهونه وبخښي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_7.mp3', '', 1761754199, 1761754199),
(30621, 'Mark 2:8', 'Mark', 2, 8, 'عیسی سمدلاسه پوه شو چې د هغوی په زړه کې څه دي. نو هغوی ته یې وویل: «تاسو ولې په خپلو زړونو کې داسې فکرونه کوئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_8.mp3', '', 1761754199, 1761754199),
(30622, 'Mark 2:9', 'Mark', 2, 9, 'کومه خبره اسانه ده چې دې شل سړي ته ووایم: ‹ستا ګناهونه وبخښل شول› یا دا چې ووایم: ‹پاڅېږه او خپله بستره واخله او وګرځه؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_9.mp3', '', 1761754199, 1761754199),
(30623, 'Mark 2:10', 'Mark', 2, 10, 'خو زه به تاسو ته ثابته کړم چې د انسان زوی د ځمکې په مخ دا اختیار لري چې ګناهونه وبخښي.» نو هغه شل سړي ته یې وویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_10.mp3', '', 1761754199, 1761754199),
(30624, 'Mark 2:11', 'Mark', 2, 11, '«زه تاته وایم پاڅېږه، بستره دې واخله او کور ته لاړ شه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_11.mp3', '', 1761754199, 1761754199),
(30625, 'Mark 2:12', 'Mark', 2, 12, 'هغه پاڅېد او په داسې حال کې چې ټولو ورته کتل، زر یې خپله بستره واخیستله او روان شو. نو هغوی ټول حیران شول او د خدای ثنا یې وویله. هغوی وویل: «داسې کار مونږ هېڅکله نه ؤ لیدلی.» عیسی یو مالیه ټولوونکي ته بلنه ورکوي (متي ۹‏:‌۹‌‏-‌۱۳ او لوقا ۵‏:‌۲۷‌‏-‌۳۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_12.mp3', '', 1761754199, 1761754199),
(30626, 'Mark 2:13', 'Mark', 2, 13, 'عیسی یوځل بیا د بحیرې غاړې ته لاړ، ګڼ شمېر خلک ورته راغلل او هغه ورته تعلیم ورکول پیل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_13.mp3', '', 1761754199, 1761754199),
(30627, 'Mark 2:14', 'Mark', 2, 14, 'کله چې هغه په لاره روان ؤ نو د حلفي زوی لاوي یې ولیده چې د مالیې ټولولو په ځای کې ناست ؤ. عیسی هغه ته وویل: «ما پسې راځه.» نو لاوي راپاڅېد او په هغه پسې روان شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_14.mp3', '', 1761754199, 1761754199),
(30628, 'Mark 2:15', 'Mark', 2, 15, 'بیا عیسی د لاوي په کور کې مېلمه شو. ډېر مالیه ټولوونکي او نور ګناهکاران چې د عیسی پیروان شوي وو هم د عیسی او د هغه د شاګردانو سره دسترخوان ته ناست وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_15.mp3', '', 1761754199, 1761754199),
(30629, 'Mark 2:16', 'Mark', 2, 16, 'کله چې د شریعت ځینو عالمانو چې د فریسیانو د ډلې څخه وو ولیدل چې عیسی د مالیه ټولوونکو او نورو ګناهکارانو سره ډوډۍ خوري، نو د هغه شاګردانو ته یې وویل: «هغه ولې د مالیه ټولوونکو او ګناهکارانو سره ډوډۍ خوري؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_16.mp3', '', 1761754199, 1761754199),
(30630, 'Mark 2:17', 'Mark', 2, 17, 'عیسی دا خبره واورېدله او هغوی ته یې وویل: «روغ خلک ډاکتر ته اړتیا نه لري بلکې ناروغان ورته اړتیا لري. زه د دې دپاره نه یم راغلی چې پرهېزګاران راوبولم، بلکې ګناهکاران راوبولم.» د روژې په هکله پوښتنه (متي ۹‏:‌۱۴‌‏-‌۱۷ او لوقا ۵‏:‌۳۳‌‏-‌۳۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_17.mp3', '', 1761754199, 1761754199),
(30631, 'Mark 2:18', 'Mark', 2, 18, 'په یو وخت کې چې د یحیی شاګردانو او فریسیانو روژه نیولې وه، نو ځینې خلک عیسی ته راغلل او د هغه څخه یې پوښتنه وکړه: «ولې د یحیی شاګردان او د فریسیانو شاګردان روژه نیسي خو ستا شاګردان روژه نه نیسي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_18.mp3', '', 1761754199, 1761754199),
(30632, 'Mark 2:19', 'Mark', 2, 19, 'عیسی ورته وویل: «ایا دا کېدای شي چې د زوم ملګري دې په داسې حال کې چې زوم ورسره وي روژه ونیسي؟ بې له شکه چې نه، ترڅو پورې چې زوم د هغوی سره وي، هغوی نه شي کولای چې روژه ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_19.mp3', '', 1761754199, 1761754199),
(30633, 'Mark 2:20', 'Mark', 2, 20, 'خو داسې وخت به راشي چې زوم به د هغوی څخه بوتلل شي، نو په هغه وخت کې به هغوی روژه ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_20.mp3', '', 1761754199, 1761754199),
(30634, 'Mark 2:21', 'Mark', 2, 21, 'هېڅوک په زړو کالیو باندې نوی پیوند نه لګوي. که داسې وکړي، نو هغه پیوند به د زړو کالیو څخه راوشلیږي او له مخکې څخه به هم یو لوی سوری په کې جوړ شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_21.mp3', '', 1761754199, 1761754199),
(30635, 'Mark 2:22', 'Mark', 2, 22, 'هېڅوک تازه شراب په زړو مشکونو کې نه اچوي. که چېرې داسې وکړي، نو شراب به هغه مشکونه وشلوي او شراب او مشکونه دواړه به له منځه لاړ شي. باید تازه شراب په نویو مشکونو کې واچول شي.» د سبت د ورځې په هکله پوښتنه (متي ۱۲‏:‌۱‌‏-‌۸ او لوقا ۶‏:‌۱‌‏-‌۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_22.mp3', '', 1761754199, 1761754199),
(30636, 'Mark 2:23', 'Mark', 2, 23, 'د سبت په یوه ورځ عیسی د غنمو په پټیو باندې تېرېده، نو شاګردانو یې د غنمو د وږو په شکولو پیل وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_23.mp3', '', 1761754199, 1761754199),
(30637, 'Mark 2:24', 'Mark', 2, 24, 'فریسیانو هغه ته وویل: «ګوره، ستا شاګردان ولې داسې کار کوي چې د سبت په ورځ روا نه دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_24.mp3', '', 1761754199, 1761754199),
(30638, 'Mark 2:25', 'Mark', 2, 25, 'عیسی ځواب ورکړ: «ایا تاسو دا نه دي لوستلي کله چې داود او د هغه ملګري وږي شوي وو او د خوراک دپاره ورسره څه نه وو، نو هغه څه وکړل؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_25.mp3', '', 1761754199, 1761754199),
(30639, 'Mark 2:26', 'Mark', 2, 26, 'هغه څنګه د لوی کاهن ابیاتار په زمانه کې د خدای کور ته ورننوت او هغه سپېڅلې ډوډۍ یې چې پرته له کاهنانو بل هېچا ته روا نه وه وخوړله او خپلو ملګرو ته یې هم ورکړه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_26.mp3', '', 1761754199, 1761754199),
(30640, 'Mark 2:27', 'Mark', 2, 27, 'بیا عیسی هغوی ته وویل: «د سبت ورځ د انسان دپاره پیدا شوې ده، نه انسان د سبت د ورځې دپاره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_27.mp3', '', 1761754199, 1761754199),
(30641, 'Mark 2:28', 'Mark', 2, 28, 'ځکه چې د انسان زوی د سبت د ورځې خاوند هم دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark2_verse_28.mp3', '', 1761754199, 1761754199),
(30642, 'Acts 23:1', 'Acts', 23, 1, 'پولوس په ځیر سره د شورا غړو ته وکتل او ویې ویل: «ای ورونو! ما تر نن ورځې پورې په پاک وجدان سره د خدای په حضور کې ژوند تېر کړی دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_1.mp3', '', 1761754199, 1761754199),
(30643, 'Acts 23:2', 'Acts', 23, 2, 'په دې خبره لوی کاهن حنانیا هغو خلکو ته چې د پولوس په خوا کې ولاړ وو، امر وکړ چې په خوله یې ووهئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_2.mp3', '', 1761754199, 1761754199),
(30644, 'Acts 23:3', 'Acts', 23, 3, 'بیا پولوس هغه ته وویل: «خدای به دې ووهي، ای په چونه باندې سپین شوی دېواله. ته ناست یې چې د شریعت له مخې زما په هکله قضاوت وکړې، خو اوس د شریعت خلاف امر کوې چې ما ووهي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_3.mp3', '', 1761754199, 1761754199),
(30645, 'Acts 23:4', 'Acts', 23, 4, 'نو هغو خلکو چې د پولوس په خوا کې ولاړ وو، وویل: «ته د خدای لوی کاهن ته سپکاوی کوې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_4.mp3', '', 1761754199, 1761754199),
(30646, 'Acts 23:5', 'Acts', 23, 5, 'پولوس ځواب ورکړ: «ای ورونو، زه نه پوهېدم چې هغه لوی کاهن دی. ځکه چې د خدای په کلام کې لیکل شوي دي: چې د خپل قوم مشر ته بدې خبرې مه کوئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_5.mp3', '', 1761754199, 1761754199),
(30647, 'Acts 23:6', 'Acts', 23, 6, 'کله چې پولوس پوه شو چې د شورا ځینې غړي صدوقیان او ځینې یې فریسیان دي، نو په لوړ اواز یې وویل: «ای ورونو! زه فریسي یم او پلار مې هم فریسي ؤ. زه په دې خاطر محاکمه کېږم چې په دې هیله یم چې مړي به بیا راژوندي کیږي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_6.mp3', '', 1761754199, 1761754199),
(30648, 'Acts 23:7', 'Acts', 23, 7, 'څنګه چې هغه دا خبره وکړه، نو د فریسیانو او صدوقیانو ترمنځ مخالفت پیدا شو او غونډه په دوو ډلو ووېشل شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_7.mp3', '', 1761754199, 1761754199),
(30649, 'Acts 23:8', 'Acts', 23, 8, '(ځکه چې صدوقیان د قیامت د ورځې، فرښتو او پېریانو څخه منکر دي، خو فریسیان دا ټول مني.)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_8.mp3', '', 1761754199, 1761754199),
(30650, 'Acts 23:9', 'Acts', 23, 9, 'په غونډه کې ډېر شورماشور او غوغا پیدا شوه او د فریسیانو د ډلې څخه د شریعت یو څو عالمان راپاڅېدل او په کلکه یې وویل: «مونږ په دې سړي کې هېڅ غلطي نه وینو. کېدای شي چې کوم روح یا فرښتې ورسره خبرې کړې وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_9.mp3', '', 1761754199, 1761754199),
(30651, 'Acts 23:10', 'Acts', 23, 10, 'دا مخالفت دومره سخت شو چې قوماندان ووېرېده چې هسې نه هغوی پولوس ټوټې ټوټې کړي، نو عسکرو ته یې امر وکړ چې غونډې ته ورننوځي او پولوس په زوره د هغوی له منځ نه راوباسي او نظامي‌قلعه ته یې بوځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_10.mp3', '', 1761754199, 1761754199),
(30652, 'Acts 23:11', 'Acts', 23, 11, 'په هماغه شپه څښتن د پولوس په خوا کې ودرېده او ویې ویل: «زړور اوسه! لکه څنګه چې تا په اورشلیم کې زما په هکله شاهدي ورکړه، نو په روم کې هم باید شاهدي ورکړې.» د پولوس په ضد دسیسه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_11.mp3', '', 1761754199, 1761754199),
(30653, 'Acts 23:12', 'Acts', 23, 12, 'کله چې ورځ شوه، نو ځینې یهودیان سره راټول شول او یوه دسیسه یې جوړه کړه او قسم یې وخوړ چې ترڅو پورې مو پولوس نه وي وژلی، نو نه به څه خورو او نه به څه څښو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_12.mp3', '', 1761754199, 1761754199),
(30654, 'Acts 23:13', 'Acts', 23, 13, 'کومو خلکو چې دا دسیسه جوړه کړې وه، شمېر یې د څلوېښتو تنو څخه زیات ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_13.mp3', '', 1761754199, 1761754199),
(30655, 'Acts 23:14', 'Acts', 23, 14, 'بیا هغوی مشرانو کاهنانو او د قوم مشرانو ته ورغلل او ویې ویل: «مونږ قسم خوړلی دی تر هغې پورې چې پولوس مو نه وي وژلی، نو مونږ به هېڅ شی ونه خورو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_14.mp3', '', 1761754199, 1761754199),
(30656, 'Acts 23:15', 'Acts', 23, 15, 'نو اوس تاسو او د شورا غړي په دې بهانه چې غواړئ د هغه په هکله سم معلومات تر‌لاسه کړئ، د قوماندان څخه وغواړئ چې پولوس تاسو ته راولي. مونږ دې ته تیار یو چې دلته د رارسېدلو څخه مخکې هغه مړ کړو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts23_verse_15.mp3', '', 1761754199, 1761754199),
